    // just below the next item is nearly wasted, while a moderately larger
    // gap can remain useful for several later items.
    let scarce_limit = (item * 0.24).max(1.0);
    if post < scarce_limit {
        let deficit = (scarce_limit - post) / scarce_limit;
        score += 8.0 + 24.0 * deficit * deficit;
    }

    // Prefer residuals close to the average residual, with a soft penalty for
    // unusually large gaps. This discourages creating a second kind of slack.
    let mean_gap = (mean - post).abs() / capacity;
    score += 6.5 * mean_gap.min(1.0);
    if post_fraction > 0.34 {
        let excess = (post_fraction - 0.34) / 0.66;
        score += 8.0 * excess * excess;
    }

