    if !is_new_bin {
        score -= 3.8 * item_fraction;
        score += 3.2 * (residual / capacity).min(1.0);

        if fitting_bins_count == 1 {
            score -= 27.0;
        } else if fitting_bins_count == 2 {
            score -= 10.0;
        } else if fitting_bins_count == 3 {
            score -= 2.5;
